import java.nio.file.*;import java.util.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Inspect{public static void main(String[]a)throws Exception{ClassNode nativeClass=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(a[0]))).accept(nativeClass,0);Set<String>names=new HashSet<>();for(MethodNode m:nativeClass.methods)names.add(m.name+m.desc);ClassNode mixin=new ClassNode();new ClassReader(Files.readAllBytes(Path.of(a[1]))).accept(mixin,0);int count=0;for(MethodNode m:mixin.methods){new Analyzer<BasicValue>(new BasicVerifier()).analyze(mixin.name,m);for(AnnotationNode an:m.visibleAnnotations)if(an.desc.endsWith("/Inject;"))for(int i=0;i<an.values.size();i+=2)if(an.values.get(i).equals("method"))for(Object target:(List<?>)an.values.get(i+1)){if(!names.contains(target.toString()))throw new AssertionError(target);count++;}}if(count!=6)throw new AssertionError(count);System.out.println("SIX_ANIMATION_MIXIN_DESCRIPTORS_MATCH_NATIVE_TaCZ_BYTECODE=PASS");}}
